<?php require_once __DIR__.'/_base.php'; $title='Request Booking'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $pid=(int)($_GET['provider']??$_POST['provider_id']??0);$s=$pdo->prepare("SELECT * FROM providers WHERE id=? AND verification_status='Approved' AND account_status='Active'");$s->execute([$pid]);$p=$s->fetch();if(!$p){echo '<div class="alert alert-danger">Provider unavailable.</div>';return;}$sv=$pdo->prepare('SELECT s.* FROM services s JOIN provider_services ps ON ps.service_id=s.id WHERE ps.provider_id=?');$sv->execute([$pid]);$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$service=(int)$_POST['service_id'];$date=post('booking_date');$time=post('booking_time');$req=post('requirements');$chk=$pdo->prepare('SELECT id FROM services WHERE id=? AND status="Active"');$chk->execute([$service]);if(!$chk->fetch()||!valid_date($date)||$date<date('Y-m-d'))$error='Please choose a valid service and future date.';else{$pdo->prepare('INSERT INTO bookings(user_id,provider_id,service_id,booking_date,booking_time,requirements,charges,status) VALUES(?,?,?,?,?,?,?,?)')->execute([$u['id'],$pid,$service,$date,$time,$req,$p['charges'],'Pending']);$bid=$pdo->lastInsertId();notify($pdo,'New booking request','A new booking request has been submitted.',$p['user_id'],$pid,'booking');flash('success','Booking request sent successfully.');redirect('bookings.php');}}?><div class="row justify-content-center"><div class="col-lg-7"><div class="service-card p-4"><h3>Book <?=e($p['name'])?></h3><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post" data-validate class="needs-validation" novalidate><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="provider_id" value="<?=$pid?>"><div class="mb-3"><label class="form-label">Service</label><select name="service_id" class="form-select" required><?php foreach($sv->fetchAll() as $x):?><option value="<?=$x['id']?>"><?=e($x['service_name'])?></option><?php endforeach;?></select></div><div class="row"><div class="col-md-6 mb-3"><label class="form-label">Date</label><input name="booking_date" type="date" min="<?=date('Y-m-d',strtotime('+1 day'))?>" class="form-control" required></div><div class="col-md-6 mb-3"><label class="form-label">Time</label><input name="booking_time" type="time" class="form-control" required></div></div><div class="mb-3"><label class="form-label">Requirements</label><textarea name="requirements" class="form-control" rows="4" placeholder="Tell the provider what assistance you need."></textarea></div><div class="alert alert-light border">Booking charge: <b>PKR <?=number_format($p['charges'],2)?></b></div><button class="btn btn-success btn-lg">Send Booking Request</button></form></div></div></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>